private static String convertToPostfix(String infixExpression) {
    Log.log("开始转化中缀表达式：" + infixExpression + "\n", logOn);
    StringBuilder postfixExpression = new StringBuilder();
    HashMap<String, Integer> priority = new HashMap<>();
    Stack<String> stack = new Stack<>();
    priority.put("^", 3);
    priority.put("*", 2);
    priority.put("/", 2);
    priority.put("+", 1);
    priority.put("-", 1);
    priority.put("(", 0);
    ArrayList<String> pieces = splitIntoPieces(infixExpression);
    for(int i = 0; i < pieces.size(); i++) {
        String piece = pieces.get(i);
        if("+".equals(piece) || "-".equals(piece) || "*".equals(piece) || "/".equals(piece)
                || "(".equals(piece) || ")".equals(piece) || "^".equals(piece)) {
            if(")".equals(piece)) {
                String top;
                while(!"(".equals(top = stack.pop())) {
                    postfixExpression.append(top).append(" ");
                }
            } else if("(".equals(piece)) {
                stack.push(piece);
            } else if(stack.isEmpty() || priority.get(piece) > priority.get(stack.getTop())) {
                stack.push(piece);
            } else {
                postfixExpression.append(stack.pop()).append(" ");
                i--;
                continue;
            }
        } else {
            postfixExpression.append(piece).append(" ");
        }
        Log.log(piece, stack.toString(), logOn);
    }
    while(!stack.isEmpty()) {
