private static ArrayList<String> splitIntoPieces(String infixExpression) {
    ArrayList<String> pieces = new ArrayList<>();
    for(int i = 0; i < infixExpression.length(); i++) {
        for(int j = i; j < infixExpression.length(); j++) {
            char current = infixExpression.charAt(j);
            if(current == '+' || current == '-' || current == '*' || current == '/'
                    || current == '(' || current == ')' || current == '^') {
                char first = infixExpression.charAt(i);
                if(first == '+' || first == '-' || first == '*' || first == '/'
                        || first == '(' || first == ')' || first == '^') {
                    pieces.add(infixExpression.substring(i, j + 1));
                    i = j;
                } else {
                    pieces.add(infixExpression.substring(i, j));
                    i = j - 1;
                }
                break;
            }
            if(j == infixExpression.length() - 1) {
                pieces.add(infixExpression.substring(i, j + 1));
                i = infixExpression.length();
                break;
            }
        }
    }
    return pieces;
}

