private static double calculatePostfixExpression(String postfixExpression) {
    Log.log("开始计算后缀表达式：" + postfixExpression + "\n", logOn);
    String[] pieces = postfixExpression.split(" ");
    Stack<Double> stack = new Stack<>();
    Double ans = 0.0;
    for(int i = 0; i < pieces.length; i++) {
        String piece = pieces[i];
        if("+".equals(piece) || "-".equals(piece) || "*".equals(piece)
                || "/".equals(piece) || "^".equals(piece)) {
            ArrayList<Double> elements = stack.popTwo();
            if("+".equals(piece)) {
                ans = elements.get(1) + elements.get(0);
            } else if("-".equals(piece)) {
                ans = elements.get(1) - elements.get(0);
            } else if("*".equals(piece)) {
                ans = elements.get(1) * elements.get(0);
            } else if("/".equals(piece)) {
                ans = elements.get(1) / elements.get(0);
            } else if("^".equals(piece)) {
                ans = Math.pow(elements.get(1), elements.get(0));
            }
            stack.push(ans);
        } else {
            stack.push(Double.valueOf(piece));
        }
        Log.log(piece, stack.toString(), logOn);
    }
    Log.log("计算完成，结果是：" + stack.getTop() + "\n\n", logOn);
    return stack.getTop();
}

