private static TreeNode findNearsetAncestor(TreeNode root, String one, String another) {
    //如果当前节点为null说明走到了叶节点都没有找到两个节点中的其中一个
    //如果当前节点为p,q之其中的一个，那么返回当前找到的节点中的一个
    if(root == null || root.getValue() == null
            || one.equals(root.getValue()) || another.equals(root.getValue())) {
        return root;
    }
    TreeNode left = findNearsetAncestor(root.getLeftNode(), one, another);
    TreeNode right = findNearsetAncestor(root.getRightNode(), one, another);
    if(left != null && left.getValue() != null && right != null && right.getValue() != null) {
        return root;
    }
    return left == null || left.getValue() == null ? right : left;
}

