private static void findAWay() {
    stack = new Stack();
    stack.push(nodeList.get((int)(Math.random() * teamNumber)));
    stack.getTop().setTrue();
    while(!stack.isFull()) {
        if(stack.isEmpty()) {
            for(int i = 0; i < teamNumber; i ++) {
                if(!nodeList.get(i).getHasGet()) {
                    stack.push(nodeList.get(i));
                    stack.getTop().setTrue();
                    break;
                }
            }
        }
        if(stack.isEmpty()) {
            System.out.println("\n该组数据无哈密顿通路！");
            System.exit(0);
        }
        int[] edges = graph[stack.getTop().getIndex()];
        ArrayList<Node> availableNodes = new ArrayList<>();
        for(int i = 0; i < teamNumber; i ++) {
            if(edges[i] == 1 && !nodeList.get(i).getHasGet()) {
                availableNodes.add(nodeList.get(i));
            }
        }
        if(availableNodes.isEmpty()) {
            stack.pop();
            continue;
        }
        stack.push(availableNodes.get((int)(Math.random() * availableNodes.size())));
        stack.getTop().setTrue();
    }
}

