//从两侧向中间查找最大值的方法
private static void findMax(int[] samples) {
    maxNumber = samples[0];
    maxIndex.clear();
    maxIndex.add(0);
    int left = 1;
    int right = samples.length - 1;
    while(left <= right) {
        if(samples[left] > maxNumber) {
            maxNumber = samples[left];
            maxIndex.clear();
            maxIndex.add(left);
        } else if(samples[left] == maxNumber) {
            maxIndex.add(left);
        }
        if(right != left) {
            if(samples[right] > maxNumber) {
                maxNumber = samples[right];
                maxIndex.clear();
                maxIndex.add(right);
            } else if(samples[right] == maxNumber) {
                maxIndex.add(right);
            }
        }
        left++;
        right--;
    }
}

