    private static HashMap<Character, Double> calculateCharChance(String string) {
        if (string == null) {
            return null;
        }
        HashMap<Character, Double> hashMap = new HashMap<Character, Double>();
        for (int i = 0; i < string.length(); ++i) {
            char c = string.charAt(i);
            if (hashMap.containsKey(Character.valueOf(c))) {
                hashMap.put(Character.valueOf(c), (Double)hashMap.get(Character.valueOf(c)) + 1.0);
                continue;
            }
            hashMap.put(Character.valueOf(c), 1.0);
        }
        HashMap<Character, Double> hashMap2 = new HashMap<Character, Double>();
        for (Map.Entry entry : hashMap.entrySet()) {
            hashMap2.put((Character)entry.getKey(), (Double)entry.getValue() / (double)string.length());
        }
        return hashMap2;
    }

    private static TreeNode buildHuffmanTree(HashMap<Character, Double> hashMap) {
        TreeNode treeNode;
        if (hashMap == null) {
            return null;
