        ArrayList<TreeNode> arrayList = new ArrayList<TreeNode>();
        leafNodes = new HashMap();
        for (Map.Entry<Character, Double> object : hashMap.entrySet()) {
            treeNode = new TreeNode(object.getKey().charValue(), object.getValue());
            arrayList.add(treeNode);
            leafNodes.put(treeNode.getCurrentChar(), treeNode);
        }
        TreeNodeComparator treeNodeComparator = new TreeNodeComparator();
        while (arrayList.size() != 1) {
            Collections.sort(arrayList, treeNodeComparator);
            TreeNode treeNode2 = (TreeNode)arrayList.remove(0);
            treeNode = (TreeNode)arrayList.remove(0);
            TreeNode treeNode3 = new TreeNode(treeNode2.getChance() + treeNode.getChance());
            treeNode3.setLeftNode(treeNode2);
            treeNode3.setRightNode(treeNode);
            treeNode2.setParentNode(treeNode3);
            treeNode.setParentNode(treeNode3);
            arrayList.add(treeNode3);
        }
        return (TreeNode)arrayList.get(0);
    }

