    private static void createGraph() {
        boolean[] blArray;
        boolean[] blArray2 = blArray = new boolean[]{true, false};
        int n = blArray2.length;
        for (int i = 0; i < n; ++i) {
            boolean bl = blArray2[i];
            for (boolean bl2 : blArray) {
                for (boolean bl3 : blArray) {
                    for (boolean bl4 : blArray) {
                        if (!Main.isValid(bl, bl2, bl3, bl4)) continue;
                        Node node = new Node(bl, bl2, bl3, bl4);
                        node.setIndex(nodes.size());
                        nodes.add(node);
                    }
                }
            }
        }
        edges = new int[nodes.size()][nodes.size()];
        for (int i = 0; i < nodes.size(); ++i) {
            for (n = 0; n < nodes.size(); ++n) {
                Main.edges[i][n] = Main.canConnect(nodes.get(i), nodes.get(n)) ? 1 : 0;
            }
        }
        visit = new boolean[nodes.size()];
    }

    private static void searchWay() {
        int n = 0;
        int n2 = 0;
        for (int i = 0; i < nodes.size(); ++i) {
            Node node = nodes.get(i);
            if (!(node.getFarmer() || node.getSheep() || node.getVegetable() || node.getWolf())) {
                n = i;
            }
            if (!node.getFarmer() || !node.getSheep() || !node.getVegetable() || !node.getWolf()) continue;
            n2 = i;
        }
        Main.DFS(nodes.get(n), nodes.get(n2));
    }

    private static void DFS(Node node, Node node2) {
        stack.push(node);
        Main.visit[node.index] = true;
        while (!stack.isEmpty()) {
            int n = stack.getTop().getIndex();
            if (n == node2.index) {
                results.add(stack.getList());
                stack.pop();
                Main.visit[node2.index] = false;
                break;
            }
            while (node.flag < nodes.size()) {
                if (edges[n][node.flag] == 1 && !visit[node.flag]) {
                    Main.DFS(nodes.get(node.flag), node2);
                }
                ++node.flag;
            }
            if (node.flag != nodes.size()) continue;
            stack.pop();
            node.flag = 0;
            Main.visit[node.index] = false;
            break;
        }
    }

