    static void check(String mode) {
        // BFS over carved passages from (0,0); all cells must be reachable (perfect maze)
        boolean[][] vis = new boolean[20][25];
        java.util.Queue<int[]> q = new java.util.LinkedList<>();
        q.add(new int[]{0,0}); vis[0][0] = true;
        int count = 0;
        while (!q.isEmpty()) {
            int[] c = q.poll(); count++;
            int r = c[0], co = c[1];
            MazeLabel l = Main.mazeLabels[r][co];
            if (l.isUpAlready() && !vis[r-1][co]) { vis[r-1][co]=true; q.add(new int[]{r-1,co}); }
            if (l.isDownAlready() && !vis[r+1][co]) { vis[r+1][co]=true; q.add(new int[]{r+1,co}); }
            if (l.isLeftAlready() && !vis[r][co-1]) { vis[r][co-1]=true; q.add(new int[]{r][co-1}); }
            if (l.isRightAlready() && !vis[r][co+1]) { vis[r][co+1]=true; q.add(new int[]{r][co+1}); }
        }
        if (count != 500) throw new RuntimeException(mode + ": only " + count + " cells reachable");
    }
}
